mapper.update:
update ujcms_friend_link_type
set order_ = order_ + 1
where order_ < #{from}
  and order_ >= #{to}

update ujcms_friend_link_type
set order_ = order_ - 1
where order_ > #{from}
  and order_ <= #{to}

update ujcms_friend_link_type
set order_ = #{order}
where id_ = #{id}

mapper.select:
select

from ujcms_friend_link_type t
where t.id_ = #{id,jdbcType=BIGINT}

select

from ujcms_friend_link_type t
where t.site_id_ = #{siteId,jdbcType=BIGINT}
  and t.alias_ = #{alias,jdbcType=VARCHAR}
order by t.order_, t.id_

select case when exists(
select *
from ujcms_friend_link_type t
where t.alias_ = #{alias}
  and t.site_id_ = #{siteId}
) then 1 else 0 end
